"use client";

import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import {
  Activity, AlertTriangle, ArrowRight, BriefcaseBusiness, CalendarClock, Check, ChevronDown, CircleDollarSign,
  ClipboardCheck, Download, FileArchive, FileCheck2, FileHeart, FileText, FolderLock, Gavel, HeartHandshake,
  Home, Landmark, LayoutDashboard, Link2, LogOut, Menu, MessageCircle, MoreHorizontal, Pencil, Plus, RefreshCw,
  Scale, Search, ShieldCheck, Stethoscope, Upload, UserRoundCheck, Users, X
} from "lucide-react";

type User = { id: string; email: string; displayName: string };
type View = "overview" | "family" | "timeline" | "claims" | "health" | "activities" | "communications" | "pensions" | "finances" | "coparenting" | "decisions" | "evidence" | "analysis" | "lawyer" | "export" | "settings";

const nav: Array<{ id: View; label: string; icon: any }> = [
  { id: "overview", label: "Tableau de bord", icon: LayoutDashboard }, { id: "family", label: "Dossier familial", icon: Users },
  { id: "timeline", label: "Chronologie", icon: CalendarClock }, { id: "claims", label: "Accusations et réponses", icon: MessageCircle },
  { id: "health", label: "Santé de l’enfant", icon: Stethoscope }, { id: "activities", label: "Activités parentales", icon: Activity },
  { id: "communications", label: "Communications", icon: HeartHandshake }, { id: "pensions", label: "Pensions alimentaires", icon: CircleDollarSign },
  { id: "finances", label: "Finances", icon: Landmark }, { id: "coparenting", label: "Coparentalité", icon: Users },
  { id: "decisions", label: "Décisions judiciaires", icon: Gavel }, { id: "evidence", label: "Documents et preuves", icon: FolderLock },
  { id: "analysis", label: "Analyse du dossier", icon: ClipboardCheck }, { id: "lawyer", label: "Préparation avocat", icon: BriefcaseBusiness },
  { id: "export", label: "Génération dossier", icon: FileArchive }, { id: "settings", label: "Paramètres", icon: ShieldCheck },
];

const moduleMeta: Partial<Record<View, { title: string; kicker: string; theme: string; description: string }>> = {
  health: { title: "Santé de l’enfant", kicker: "Suivi familial", theme: "Santé", description: "Consultations, examens, prescriptions, rendez-vous et communications médicales utiles au dossier." },
  activities: { title: "Implication parentale", kicker: "Vie quotidienne", theme: "Activités parentales", description: "Activités scolaires, sportives, soins, démarches, vacances et dépenses engagées pour l’enfant." },
  communications: { title: "Contacts et appels", kicker: "Lien avec l’enfant", theme: "Communications", description: "Consignez les appels prévus et réalisés sans déduire automatiquement une entrave d’un contact manqué." },
  pensions: { title: "Pensions alimentaires", kicker: "Suivi financier", theme: "Pension", description: "Échéances, versements, paiements partiels et régularisations à faire vérifier si nécessaire." },
  finances: { title: "Finances du parent", kicker: "Situation financière", theme: "Finances", description: "Revenus, charges et dépenses concernant l’enfant, avec distinction entre faits documentés et montants contestés." },
  coparenting: { title: "Communication et coparentalité", kicker: "Échanges utiles", theme: "Coparentalité", description: "Conservez le contexte complet des demandes, propositions, réponses, accords et refus exprimés." },
  decisions: { title: "Décisions et obligations", kicker: "Cadre judiciaire", theme: "Décision judiciaire", description: "Référencez les décisions, les obligations applicables et les événements d’exécution ou de difficulté." },
};

export function Workspace({ user }: { user: User }) {
  const [cases, setCases] = useState<any[]>([]);
  const [caseId, setCaseId] = useState("");
  const [data, setData] = useState<any>(null);
  const [view, setView] = useState<View>("overview");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [modal, setModal] = useState<null | "case" | "event" | "evidence" | "request" | "claim">(null);
  const [editing, setEditing] = useState<null | { kind: "event" | "evidence" | "request" | "claim"; item: any }>(null);
  const [presetTheme, setPresetTheme] = useState("");
  const [mobileNav, setMobileNav] = useState(false);

  const loadCases = useCallback(async () => {
    const response = await fetch("/api/cases");
    if (response.status === 401) { window.location.href = "/connexion"; return; }
    const result = await response.json();
    setCases(result);
    setCaseId((current) => current || result[0]?.id || "");
    setLoading(false);
  }, []);
  const loadWorkspace = useCallback(async () => {
    if (!caseId) { setData(null); return; }
    const response = await fetch(`/api/cases/${caseId}/workspace`, { cache: "no-store" });
    if (response.ok) setData(await response.json());
  }, [caseId]);
  useEffect(() => { loadCases().catch(() => { setError("Impossible de charger les dossiers."); setLoading(false); }); }, [loadCases]);
  useEffect(() => { loadWorkspace().catch(() => setError("Impossible de charger ce dossier.")); }, [loadWorkspace]);

  function refreshed() { setModal(null); setEditing(null); loadCases(); loadWorkspace(); }
  function openEvent(theme = "") { setPresetTheme(theme); setModal("event"); }
  function edit(kind: "event" | "evidence" | "request" | "claim", item: any) { setEditing({ kind, item }); }
  async function logout() { await fetch("/api/auth/logout", { method: "POST" }); window.location.href = "/connexion"; }
  const meta = moduleMeta[view];

  return <div className="min-h-screen bg-cream">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[278px] flex-col bg-[#173b2b] text-white transition-transform lg:translate-x-0 ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-20 items-center justify-between border-b border-white/10 px-6">
        <div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-white/10"><Scale size={21}/></span><div><div className="font-semibold">JAF Dossier</div><div className="text-[11px] text-white/60">Espace confidentiel</div></div></div>
        <button className="lg:hidden" onClick={() => setMobileNav(false)} aria-label="Fermer le menu"><X size={20}/></button>
      </div>
      <nav className="scrollbar-thin flex-1 overflow-y-auto px-3 py-5" aria-label="Navigation principale">
        {nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => { setView(id); setMobileNav(false); }} className={`mb-1 flex min-h-11 w-full items-center gap-3 rounded-xl px-3.5 text-left text-[13px] transition ${view === id ? "bg-white text-forest shadow-sm" : "text-white/72 hover:bg-white/8 hover:text-white"}`}><Icon size={17}/><span>{label}</span></button>)}
      </nav>
      <div className="border-t border-white/10 p-4">
        <div className="flex items-center gap-3 rounded-xl bg-white/5 p-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-[#dbe9df] text-sm font-bold text-forest">{user.displayName.slice(0,1).toUpperCase()}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium">{user.displayName}</div><div className="truncate text-[11px] text-white/55">{user.email}</div></div><button onClick={logout} aria-label="Se déconnecter" className="text-white/60 hover:text-white"><LogOut size={17}/></button></div>
      </div>
    </aside>
    {mobileNav && <button className="fixed inset-0 z-30 bg-black/30 lg:hidden" onClick={() => setMobileNav(false)} aria-label="Fermer le menu" />}
    <div className="lg:pl-[278px]">
      <header className="sticky top-0 z-20 flex h-20 items-center gap-3 border-b border-line bg-cream/95 px-4 backdrop-blur md:px-8">
        <button className="btn-secondary !h-10 !min-h-10 !px-3 lg:hidden" onClick={() => setMobileNav(true)} aria-label="Ouvrir le menu"><Menu size={18}/></button>
        <div className="relative min-w-0 flex-1 md:max-w-sm">
          <select aria-label="Dossier actif" className="field !py-2.5 pr-10 font-semibold" value={caseId} onChange={(e) => setCaseId(e.target.value)} disabled={!cases.length}>
            {!cases.length && <option>Aucun dossier</option>}{cases.map((item) => <option key={item.id} value={item.id}>{item.reference} — {item.title}</option>)}
          </select><ChevronDown className="pointer-events-none absolute right-3 top-3 text-stone-400" size={16}/>
        </div>
        <div className="hidden flex-1 md:block" />
        <button className="btn-secondary hidden xl:inline-flex"><Search size={16}/>Rechercher</button>
        <button className="btn-primary" onClick={() => cases.length ? openEvent() : setModal("case")}><Plus size={17}/><span className="hidden sm:inline">Ajouter</span></button>
      </header>
      <main className="mx-auto max-w-[1500px] p-4 md:p-8">
        {error && <div className="mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800">{error}</div>}
        {loading ? <Loading /> : !cases.length ? <EmptyStart onCreate={() => setModal("case")} /> : !data ? <Loading /> :
          <>
            {view === "overview" && <Overview data={data} setView={setView} onEvent={() => openEvent()} onEvidence={() => setModal("evidence")} onEditEvent={(item:any) => edit("event", item)} />}
            {view === "family" && <Family data={data} />}
            {view === "timeline" && <Timeline data={data} onAdd={() => openEvent()} onEdit={(item:any) => edit("event", item)} />}
            {view === "claims" && <Claims data={data} onAdd={() => setModal("claim")} onEdit={(item:any) => edit("claim", item)} />}
            {view === "evidence" && <Evidence data={data} onAdd={() => setModal("evidence")} onEdit={(item:any) => edit("evidence", item)} />}
            {view === "analysis" && <Analysis data={data} onRequest={() => setModal("request")} onRefresh={loadWorkspace} onEdit={(item:any) => edit("request", item)} />}
            {view === "lawyer" && <Lawyer data={data} onRequest={() => setModal("request")} />}
            {view === "export" && <ExportPanel data={data} onRefresh={loadWorkspace} />}
            {view === "settings" && <Settings data={data} />}
            {meta && <ModuleView data={data} {...meta} onAdd={() => openEvent(meta.theme)} onEdit={(item:any) => edit("event", item)} />}
          </>}
      </main>
    </div>
    {modal && <Modal title={{case:"Nouveau dossier familial",event:"Ajouter un événement",evidence:"Importer une preuve",request:"Nouvelle demande à discuter",claim:"Ajouter une allégation"}[modal]} onClose={() => setModal(null)}>
      {modal === "case" && <CaseForm onDone={refreshed} />}
      {modal === "event" && <EventForm caseId={caseId} data={data} presetTheme={presetTheme} onDone={refreshed} />}
      {modal === "evidence" && <EvidenceForm caseId={caseId} onDone={refreshed} />}
      {modal === "request" && <RequestForm caseId={caseId} data={data} onDone={refreshed} />}
      {modal === "claim" && <ClaimForm caseId={caseId} onDone={refreshed} />}
    </Modal>}
    {editing && <Modal title={{ event: "Modifier l’événement", evidence: "Modifier les informations de la preuve", request: "Modifier la demande", claim: "Modifier l’allégation" }[editing.kind]} onClose={() => setEditing(null)}>
      {editing.kind === "event" && <EventForm caseId={caseId} data={data} presetTheme="" item={editing.item} onDone={refreshed} />}
      {editing.kind === "evidence" && <EvidenceMetadataForm caseId={caseId} item={editing.item} onDone={refreshed} />}
      {editing.kind === "request" && <RequestForm caseId={caseId} data={data} item={editing.item} onDone={refreshed} />}
      {editing.kind === "claim" && <ClaimForm caseId={caseId} item={editing.item} onDone={refreshed} />}
    </Modal>}
  </div>;
}

function PageTitle({ kicker, title, description, actions }: { kicker: string; title: string; description: string; actions?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.15em] text-forest">{kicker}</p><h1 className="text-3xl font-semibold tracking-[-.035em] md:text-[2.35rem]">{title}</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-stone-600">{description}</p></div>{actions && <div className="flex shrink-0 gap-2">{actions}</div>}</div>;
}
function Loading() { return <div className="grid min-h-[60vh] place-items-center"><div className="text-center"><RefreshCw className="mx-auto animate-spin text-forest"/><p className="mt-3 text-sm text-stone-500">Chargement de l’espace sécurisé…</p></div></div>; }
function EmptyStart({ onCreate }: { onCreate: () => void }) { return <div className="grid min-h-[72vh] place-items-center"><div className="max-w-xl text-center"><span className="mx-auto grid h-20 w-20 place-items-center rounded-[1.6rem] bg-sage text-forest"><FolderLock size={34}/></span><h1 className="mt-7 text-4xl font-semibold tracking-[-.04em]">Commencez par votre dossier familial</h1><p className="mt-4 leading-7 text-stone-600">Créez le cadre du dossier. Vous pourrez ensuite ajouter les faits, les pièces, les demandes et les points à soumettre à votre avocat.</p><button className="btn-primary mt-7" onClick={onCreate}><Plus size={17}/>Créer mon premier dossier</button></div></div>; }

function Overview({ data, setView, onEvent, onEvidence, onEditEvent }: any) {
  const linkedRequests = data.requests.filter((r:any) => r.eventLinks.length && r.evidenceLinks.length).length;
  const cards = [
    { label:"Événements", value:data.events.length, icon:CalendarClock, tone:"bg-blue-50 text-blue-700" }, { label:"Pièces", value:data.evidence.length, icon:FileCheck2, tone:"bg-emerald-50 text-emerald-700" },
    { label:"Demandes étayées", value:`${linkedRequests}/${data.requests.length}`, icon:Link2, tone:"bg-violet-50 text-violet-700" }, { label:"Alertes à vérifier", value:data.qualityAlerts.length, icon:AlertTriangle, tone:"bg-amber-50 text-amber-700" },
  ];
  const completeness = Math.min(100, [data.events.length>0,data.evidence.length>0,data.requests.length>0,data.children.length>0,data.qualityAlerts.length===0].filter(Boolean).length*20);
  return <>
    <PageTitle kicker="Vue d’ensemble" title={data.title} description={`Dossier ${data.reference} · Les indicateurs mesurent uniquement la complétude documentaire.`} actions={<><button className="btn-secondary" onClick={onEvidence}><Upload size={16}/>Importer une pièce</button><button className="btn-primary" onClick={onEvent}><Plus size={16}/>Ajouter un fait</button></>} />
    <section className="card mb-6 overflow-hidden bg-forest text-white"><div className="grid gap-8 p-6 md:p-8 lg:grid-cols-[1.2fr_.8fr] lg:items-center"><div><div className="badge bg-white/10 text-white">Préparation en cours</div><h2 className="mt-5 max-w-2xl text-2xl font-semibold tracking-[-.025em]">Avancez une information vérifiable à la fois.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-white/70">Reliez les faits aux pièces, puis aux demandes à discuter avec votre avocat. Les informations défavorables restent visibles pour préparer les difficultés honnêtement.</p></div><div><div className="mb-2 flex justify-between text-sm"><span>Complétude des rubriques principales</span><span className="font-semibold">{completeness}%</span></div><div className="h-2.5 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#f0c172]" style={{width:`${completeness}%`}}/></div><button onClick={() => setView("analysis")} className="mt-4 flex items-center gap-2 text-sm font-semibold text-[#f6d69f]">Voir les points à compléter <ArrowRight size={15}/></button></div></div></section>
    <section className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(({label,value,icon:Icon,tone}) => <div className="card p-5" key={label}><div className={`mb-5 grid h-10 w-10 place-items-center rounded-xl ${tone}`}><Icon size={19}/></div><div className="text-3xl font-semibold tracking-tight">{value}</div><div className="mt-1 text-sm text-stone-500">{label}</div></div>)}</section>
    <div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]">
      <section className="card p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><h2 className="font-semibold">Derniers événements</h2><button className="text-sm font-semibold text-forest" onClick={() => setView("timeline")}>Tout afficher</button></div><div className="space-y-1">{data.events.slice(0,5).map((e:any) => <EventRow key={e.id} event={e} onEdit={() => onEditEvent(e)}/>) }{!data.events.length && <EmptyLine text="Aucun événement enregistré."/>}</div></section>
      <section className="card p-5 md:p-6"><h2 className="font-semibold">Prochaines actions</h2><div className="mt-5 space-y-3"><Action done={data.children.length>0} text="Renseigner l’enfant concerné"/><Action done={data.events.length>0} text="Ajouter un premier fait"/><Action done={data.evidence.length>0} text="Importer une pièce originale"/><Action done={data.requests.length>0} text="Préparer une demande à discuter"/><Action done={data.qualityAlerts.length===0&&data.events.length>0} text="Lancer le contrôle qualité"/></div></section>
    </div>
  </>;
}

function EventRow({ event, onEdit }: any) { return <div className="flex gap-4 rounded-xl px-2 py-3 hover:bg-stone-50"><div className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-amber"/><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-semibold">{event.title}</span>{event.needsVerification && <span className="badge bg-amber-50 text-amber-700">À vérifier</span>}{event.unfavorable && <span className="badge bg-rose-50 text-rose-700">Défavorable</span>}<span className="flex-1"/>{onEdit&&<button className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-semibold text-forest hover:bg-sage" onClick={onEdit}><Pencil size={13}/>Modifier</button>}</div><p className="mt-1 line-clamp-2 text-sm leading-5 text-stone-600">{event.description}</p><p className="mt-1.5 text-xs text-stone-400">{new Date(event.occurredAt).toLocaleString("fr-FR")} · {event.theme} · {event.evidenceLinks.length} pièce(s)</p></div></div>; }
function Action({done,text}:{done:boolean;text:string}) { return <div className="flex items-center gap-3 text-sm"><span className={`grid h-6 w-6 place-items-center rounded-full ${done?"bg-emerald-100 text-emerald-700":"border border-stone-300 text-stone-300"}`}>{done?<Check size={14}/>:null}</span><span className={done?"text-stone-400 line-through":"text-stone-700"}>{text}</span></div>; }
function EmptyLine({text}:{text:string}) { return <div className="rounded-xl border border-dashed border-line p-8 text-center text-sm text-stone-500">{text}</div>; }
function formatDate(value: string | null | undefined) { return value ? new Date(value).toLocaleDateString("fr-FR") : "Non renseignée"; }
function toDateInput(value: string | null | undefined) { return value ? new Date(value).toISOString().slice(0, 10) : ""; }
function toDateTimeInput(value: string | null | undefined) { if (!value) return ""; const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16); }

function Family({ data }: any) { const fields=[["Référence",data.reference],["Parent utilisateur",data.parentIdentity],["Autre parent",data.otherParentIdentity],["Tribunal",data.court],["Prochaine audience",data.nextHearingAt?new Date(data.nextHearingAt).toLocaleString("fr-FR"):null],["Avocat",data.lawyerName]]; return <><PageTitle kicker="Cadre du dossier" title="Dossier familial" description="Identités, enfants, procédure et contexte actuel. Les informations saisies ici structurent tous les exports."/><div className="grid gap-6 xl:grid-cols-[1fr_.8fr]"><section className="card p-6"><h2 className="text-lg font-semibold">Informations principales</h2><dl className="mt-5 divide-y divide-line">{fields.map(([k,v])=><div className="grid gap-1 py-4 sm:grid-cols-[180px_1fr]" key={k}><dt className="text-sm text-stone-500">{k}</dt><dd className="text-sm font-medium">{v||"Non renseigné"}</dd></div>)}</dl></section><section className="card p-6"><h2 className="text-lg font-semibold">Enfant(s)</h2><div className="mt-5 space-y-3">{data.children.map((c:any)=><div className="rounded-xl bg-stone-50 p-4" key={c.id}><div className="font-semibold">{c.firstName} {c.lastName}</div><div className="mt-1 text-sm text-stone-500">{c.birthDate?`Né(e) le ${new Date(c.birthDate).toLocaleDateString("fr-FR")}`:"Date de naissance non renseignée"}</div></div>)}{!data.children.length&&<EmptyLine text="Aucun enfant renseigné."/>}</div></section></div></>; }

function Timeline({ data, onAdd, onEdit }: any) { return <><PageTitle kicker="Constitution des faits" title="Chronologie" description="Les formulations doivent rester factuelles. Une source et un statut distincts permettent de ne pas confondre constat, récit, document et interprétation." actions={<button className="btn-primary" onClick={onAdd}><Plus size={16}/>Ajouter un événement</button>}/><section className="card overflow-hidden"><div className="flex flex-col gap-3 border-b border-line p-4 md:flex-row md:items-center"><div className="relative flex-1"><Search className="absolute left-3 top-3 text-stone-400" size={16}/><input className="field !py-2.5 pl-9" placeholder="Rechercher dans la chronologie"/></div><select className="field !w-auto !py-2.5"><option>Tous les thèmes</option></select><select className="field !w-auto !py-2.5"><option>Tous les statuts</option></select></div><div className="divide-y divide-line p-2 md:p-4">{data.events.map((e:any)=><EventRow key={e.id} event={e} onEdit={() => onEdit(e)}/>)}{!data.events.length&&<EmptyLine text="La chronologie est vide. Ajoutez un premier fait daté."/>}</div></section></>; }

function Evidence({data,onAdd,onEdit}:any) {
  const [query, setQuery] = useState("");
  const normalized = query.trim().toLocaleLowerCase("fr");
  const items = data.evidence.filter((e:any) => !normalized || [e.pieceReference, e.originalName, e.category, e.source].some((value) => value?.toLocaleLowerCase("fr").includes(normalized)));
  return <><PageTitle kicker="Bibliothèque documentaire" title="Documents et preuves" description="Chaque original est conservé sans altération, identifié par une référence stable et une empreinte SHA‑256." actions={<button className="btn-primary" onClick={onAdd}><Upload size={16}/>Importer une pièce</button>}/>
    {!!data.evidence.length&&<div className="relative mb-5 max-w-xl"><Search className="absolute left-3 top-3 text-stone-400" size={16}/><input className="field !py-2.5 pl-9" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher par référence, nom, catégorie ou source" aria-label="Rechercher une preuve"/></div>}
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map((e:any)=><article className="card p-5" key={e.id}><div className="flex items-start justify-between"><span className="grid h-11 w-11 place-items-center rounded-xl bg-sage text-forest"><FileText size={20}/></span><span className="badge bg-stone-100 text-stone-700">{e.pieceReference}</span></div><h2 className="mt-5 truncate font-semibold" title={e.originalName}>{e.originalName}</h2><p className="mt-1 text-sm text-stone-500">{e.category} · {(e.size/1024).toFixed(0)} Ko</p><dl className="mt-3 grid grid-cols-2 gap-2 rounded-xl border border-line bg-white p-3 text-xs"><div><dt className="text-stone-400">Date du document</dt><dd className="mt-1 font-medium text-stone-700">{formatDate(e.documentDate)}</dd></div><div><dt className="text-stone-400">Importée le</dt><dd className="mt-1 font-medium text-stone-700">{formatDate(e.createdAt)}</dd></div></dl><div className="mt-3 rounded-lg bg-stone-50 px-3 py-2 font-mono text-[10px] text-stone-500" title={e.sha256}>SHA‑256 · {e.sha256.slice(0,18)}…</div><div className="mt-4 flex flex-wrap items-center justify-between gap-2 text-xs text-stone-500"><span>{e.eventLinks.length} fait(s) · {e.requestLinks.length} demande(s)</span><div className="flex items-center gap-3"><button className="inline-flex items-center gap-1 font-semibold text-forest" onClick={() => onEdit(e)}><Pencil size={13}/>Modifier</button><a className="font-semibold text-forest" href={`/api/cases/${data.id}/evidence/${e.id}`}>Télécharger</a></div></div></article>)}{!data.evidence.length&&<div className="md:col-span-2 xl:col-span-3"><EmptyLine text="Aucune pièce importée. Les originaux seront stockés hors des fichiers publics."/></div>}{data.evidence.length>0&&!items.length&&<div className="md:col-span-2 xl:col-span-3"><EmptyLine text="Aucune pièce ne correspond à cette recherche."/></div>}</div></>;
}

function Claims({data,onAdd,onEdit}:any) { return <><PageTitle kicker="Analyse contradictoire" title="Accusations et réponses" description="Une allégation n’est jamais qualifiée automatiquement de fausse. Documentez la source, la réponse factuelle et les vérifications nécessaires." actions={<button className="btn-primary" onClick={onAdd}><Plus size={16}/>Ajouter</button>}/><div className="space-y-4">{data.allegations.map((a:any)=><article className="card p-5 md:p-6" key={a.id}><div className="mb-4 flex flex-wrap items-center gap-2"><span className="badge bg-stone-100 text-stone-700">{a.reference}</span><span className="badge bg-blue-50 text-blue-700">{a.theme}</span>{a.unfavorableToUser&&<span className="badge bg-rose-50 text-rose-700">Élément défavorable</span>}<span className="flex-1"/><button className="inline-flex items-center gap-1 text-xs font-semibold text-forest" onClick={() => onEdit(a)}><Pencil size={13}/>Modifier</button></div><div className="grid gap-5 lg:grid-cols-2"><div><div className="label">Allégation · source : {a.source}</div><p className="text-sm leading-6">{a.allegation}</p></div><div className="rounded-xl bg-stone-50 p-4"><div className="label">Réponse factuelle</div><p className="text-sm leading-6">{a.response||"À préparer"}</p>{a.verificationPoint&&<p className="mt-3 text-xs text-amber-700">À vérifier : {a.verificationPoint}</p>}</div></div></article>)}{!data.allegations.length&&<EmptyLine text="Aucune allégation consignée."/>}</div></>; }

function Analysis({data,onRequest,onRefresh,onEdit}:any) { const [running,setRunning]=useState(false); async function run(){setRunning(true);await fetch(`/api/cases/${data.id}/quality`,{method:"POST"});await onRefresh();setRunning(false);} return <><PageTitle kicker="Matrice et cohérence" title="Analyse du dossier" description="Visualisez le chemin Demande → Fait → Preuve, puis les faiblesses documentaires à faire vérifier." actions={<><button className="btn-secondary" onClick={run} disabled={running}><RefreshCw size={16} className={running?"animate-spin":""}/>Contrôler</button><button className="btn-primary" onClick={onRequest}><Plus size={16}/>Ajouter une demande</button></>}/><section className="card mb-6 overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-stone-50 text-xs uppercase tracking-wider text-stone-500"><tr>{["Demande ou point litigieux","Faits associés","Preuves","Actions"].map(h=><th className="px-5 py-4" key={h}>{h}</th>)}</tr></thead><tbody className="divide-y divide-line">{data.requests.map((r:any)=><tr key={r.id}><td className="px-5 py-4"><div className="font-semibold">{r.title}</div><div className="mt-1 max-w-sm text-xs text-stone-500">{r.objective}</div></td><td className="px-5 py-4">{r.eventLinks.length?<div className="space-y-1">{r.eventLinks.map((l:any)=><div key={l.eventId}>{l.event.title}</div>)}</div>:<span className="badge bg-amber-50 text-amber-700">Fait absent</span>}</td><td className="px-5 py-4">{r.evidenceLinks.length?r.evidenceLinks.map((l:any)=>l.evidence.pieceReference).join(", "):<span className="badge bg-amber-50 text-amber-700">Preuve absente</span>}</td><td className="px-5 py-4"><button className="inline-flex items-center gap-1 font-semibold text-forest" onClick={() => onEdit(r)}><Pencil size={13}/>Modifier</button></td></tr>)}{!data.requests.length&&<tr><td colSpan={4} className="p-8 text-center text-stone-500">Aucune demande envisagée.</td></tr>}</tbody></table></section><section className="card p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><h2 className="font-semibold">Alertes documentaires</h2><span className="text-sm text-stone-500">{data.qualityAlerts.length} point(s)</span></div><div className="space-y-3">{data.qualityAlerts.map((a:any)=><div className={`flex gap-3 rounded-xl border p-4 ${a.severity==="BLOCKING"?"border-red-200 bg-red-50":"border-amber-200 bg-amber-50"}`} key={a.id}><AlertTriangle className={a.severity==="BLOCKING"?"text-red-700":"text-amber-700"} size={18}/><div><div className="text-sm font-semibold">{a.ruleCode.replaceAll("_"," ")}</div><p className="mt-1 text-sm leading-5 text-stone-700">{a.explanation}</p><p className="mt-1 text-xs text-stone-500">Cette alerte ne préjuge pas de la recevabilité juridique.</p></div></div>)}{!data.qualityAlerts.length&&<EmptyLine text="Lancez le contrôle pour rechercher les informations manquantes et incohérences simples."/>}</div></section></>; }

function Lawyer({data,onRequest}:any){return <><PageTitle kicker="Préparer mon rendez-vous" title="La vue essentielle pour votre avocat" description="Une synthèse des faits, demandes, preuves et incertitudes. Cette vue reste un document de travail à valider avec le professionnel." actions={<button className="btn-primary" onClick={onRequest}><Plus size={16}/>Nouvelle demande</button>}/><div className="grid gap-6 lg:grid-cols-2"><Summary title="Situation" items={[`Dossier ${data.reference} — ${data.title}`,`${data.events.length} événements et ${data.evidence.length} pièces`,data.nextHearingAt?`Prochaine audience : ${new Date(data.nextHearingAt).toLocaleString("fr-FR")}`:"Prochaine audience non renseignée"]}/><Summary title="Demandes envisagées" items={data.requests.map((r:any)=>`${r.title} — ${r.objective}`)}/><Summary title="Éléments contestés" items={data.allegations.map((a:any)=>`${a.reference} — ${a.allegation}`)}/><Summary title="Risques et incertitudes" items={[...data.events.filter((e:any)=>e.unfavorable).map((e:any)=>e.title),...data.qualityAlerts.map((a:any)=>a.explanation)]}/></div></>}
function Summary({title,items}:{title:string;items:string[]}){return <section className="card p-6"><h2 className="text-lg font-semibold">{title}</h2><ul className="mt-4 space-y-3">{items.length?items.map((x,i)=><li key={i} className="flex gap-3 text-sm leading-6"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-amber"/>{x}</li>):<li className="text-sm text-stone-500">Aucune information enregistrée.</li>}</ul></section>}

function ExportPanel({data,onRefresh}:any){const [busy,setBusy]=useState(false);const [error,setError]=useState("");async function generate(){setBusy(true);setError("");const r=await fetch(`/api/cases/${data.id}/export`,{method:"POST"});if(!r.ok){const d=await r.json();setError(d.error||"Échec de la génération");setBusy(false);return;}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=r.headers.get("content-disposition")?.match(/filename="(.+)"/)?.[1]||"DOSSIER_AVOCAT.zip";a.click();URL.revokeObjectURL(url);setBusy(false);onRefresh();}return <><PageTitle kicker="Production documentaire" title="Générer mon dossier pour l’avocat" description="Créez une nouvelle version sans écraser les précédentes. Le ZIP contient la synthèse, le dossier factuel, les tableaux, les originaux et le manifeste d’intégrité."/><section className="card overflow-hidden"><div className="grid gap-8 p-6 md:p-8 lg:grid-cols-[1fr_.85fr]"><div><span className="grid h-14 w-14 place-items-center rounded-2xl bg-sage text-forest"><FileArchive size={27}/></span><h2 className="mt-5 text-2xl font-semibold">Archive avocat complète</h2><p className="mt-3 max-w-xl text-sm leading-6 text-stone-600">La génération reprend les informations actuellement enregistrées. Vérifiez au préalable les alertes, les références et les données excessivement sensibles.</p><div className="mt-6 grid grid-cols-2 gap-3 text-sm sm:grid-cols-3">{[[data.events.length,"faits"],[data.evidence.length,"pièces"],[data.requests.length,"demandes"]].map(([v,l])=><div className="rounded-xl bg-stone-50 p-4" key={String(l)}><div className="text-2xl font-semibold">{v}</div><div className="text-stone-500">{l}</div></div>)}</div>{error&&<p className="mt-4 text-sm text-red-700">{error}</p>}<button className="btn-primary mt-6" onClick={generate} disabled={busy}><Download size={17}/>{busy?"Génération en cours…":"Générer et télécharger le ZIP"}</button></div><div className="rounded-2xl border border-line bg-stone-50 p-5"><h3 className="font-semibold">Contenu produit</h3><ul className="mt-4 space-y-3 text-sm text-stone-600">{["Note de synthèse PDF + DOCX","Dossier factuel PDF + DOCX","Chronologie XLSX","Tableau contradictoire XLSX","Pièces originales référencées","Bordereau et manifeste SHA‑256"].map(x=><li className="flex gap-2" key={x}><Check size={16} className="mt-0.5 text-emerald-700"/>{x}</li>)}</ul></div></div><div className="border-t border-line p-6"><h3 className="font-semibold">Historique des versions</h3><div className="mt-3 space-y-2">{data.exports.map((e:any)=><div className="flex items-center justify-between rounded-xl bg-stone-50 px-4 py-3 text-sm" key={e.id}><span>{e.fileName}</span><span className="text-stone-500">{new Date(e.createdAt).toLocaleString("fr-FR")}</span></div>)}{!data.exports.length&&<p className="text-sm text-stone-500">Aucun export généré.</p>}</div></div></section></>}

function ModuleView({data,title,kicker,theme,description,onAdd,onEdit}:any){const events=data.events.filter((e:any)=>e.theme.toLowerCase().includes(theme.toLowerCase().split(" ")[0]));return <><PageTitle kicker={kicker} title={title} description={description} actions={<button className="btn-primary" onClick={onAdd}><Plus size={16}/>Ajouter une entrée</button>}/><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><section className="card p-5 md:p-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-semibold">Éléments documentés</h2><span className="text-sm text-stone-500">{events.length} entrée(s)</span></div><div className="space-y-1">{events.map((e:any)=><EventRow event={e} key={e.id} onEdit={() => onEdit(e)}/>)}{!events.length&&<EmptyLine text="Aucune information enregistrée dans ce module."/>}</div></section><section className="card p-6"><h2 className="font-semibold">Règle de prudence</h2><p className="mt-3 text-sm leading-6 text-stone-600">Consignez uniquement les informations utiles, datées et sourcées. L’application ne tire aucune conclusion juridique automatique à partir de données partielles.</p><div className="mt-5 rounded-xl bg-sage/70 p-4 text-sm leading-6 text-forest"><strong>Bon réflexe :</strong> joindre le document complet et son contexte, pas seulement une capture isolée.</div></section></div></>}

function Settings({data}:any){return <><PageTitle kicker="Installation locale" title="Paramètres et sauvegardes" description="Votre installation conserve la base, les originaux et les exports dans des volumes persistants distincts."/><div className="grid gap-6 lg:grid-cols-2"><section className="card p-6"><ShieldCheck className="text-forest"/><h2 className="mt-4 text-lg font-semibold">Protection des données</h2><ul className="mt-4 space-y-3 text-sm leading-6 text-stone-600"><li>Accès lié au compte local et cookie HttpOnly.</li><li>Originaux stockés hors du dossier web public.</li><li>Contrôle d’intégrité SHA‑256 à l’import.</li><li>PostgreSQL non exposé par Docker Compose.</li></ul></section><section className="card p-6"><FileHeart className="text-forest"/><h2 className="mt-4 text-lg font-semibold">Sauvegarde</h2><p className="mt-3 text-sm leading-6 text-stone-600">Sauvegardez ensemble les volumes de base de données, de pièces et d’exports. Testez régulièrement la restauration sur une autre installation avant d’en dépendre.</p><div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">Le chiffrement d’une sauvegarde et le déploiement multiutilisateur nécessitent une analyse complémentaire.</div></section></div></>}

function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){return <div className="fixed inset-0 z-50 grid place-items-end bg-black/45 p-0 sm:place-items-center sm:p-4" role="dialog" aria-modal="true"><div className="max-h-[94vh] w-full overflow-y-auto rounded-t-[1.5rem] bg-cream shadow-2xl sm:max-w-2xl sm:rounded-[1.5rem]"><div className="sticky top-0 z-10 flex items-center justify-between border-b border-line bg-cream/95 px-5 py-4 backdrop-blur"><h2 className="text-lg font-semibold">{title}</h2><button className="grid h-10 w-10 place-items-center rounded-xl hover:bg-stone-200" onClick={onClose} aria-label="Fermer"><X size={19}/></button></div><div className="p-5 sm:p-6">{children}</div></div></div>}

function Submit({busy,label="Enregistrer"}:{busy:boolean;label?:string}){return <div className="mt-6 flex justify-end"><button className="btn-primary" disabled={busy}>{busy?"Enregistrement…":label}<ArrowRight size={16}/></button></div>}
function useSubmit(url:string,onDone:()=>void,multipart=false,method="POST"){const[busy,setBusy]=useState(false);const[error,setError]=useState("");async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError("");const fd=new FormData(event.currentTarget);let body:BodyInit;let headers:any=undefined;if(multipart)body=fd;else{const obj:any={};fd.forEach((v,k)=>{if(k.startsWith("bool_"))obj[k.slice(5)]=v==="on";else if(k.endsWith("Ids"))obj[k]=fd.getAll(k);else if(k==="importance")obj[k]=Number(v);else obj[k]=v;});body=JSON.stringify(obj);headers={"Content-Type":"application/json"};}const r=await fetch(url,{method,headers,body});const d=await r.json().catch(()=>({}));if(!r.ok){setError(d.error||"Enregistrement impossible");setBusy(false);return;}onDone();}return{busy,error,submit}}

function CaseForm({onDone}:any){const s=useSubmit("/api/cases",onDone);return <form onSubmit={s.submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Référence interne"><input className="field" name="reference" required pattern="[A-Za-z0-9_-]+" placeholder="DUPONT-2026"/></Field><Field label="Nom du dossier"><input className="field" name="title" required placeholder="Organisation familiale"/></Field></div><Field label="Identité du parent utilisateur"><input className="field" name="parentIdentity" required placeholder="Nom et prénom"/></Field><Field label="Identité de l’autre parent"><input className="field" name="otherParentIdentity" placeholder="Facultatif"/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Prénom de l’enfant"><input className="field" name="childFirstName" placeholder="Facultatif"/></Field><Field label="Date de naissance"><input className="field" name="childBirthDate" type="date"/></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Tribunal concerné"><input className="field" name="court" placeholder="Si connu"/></Field><Field label="Prochaine audience"><input className="field" name="nextHearingAt" type="datetime-local"/></Field></div>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label="Créer le dossier"/></form>}
function EventForm({caseId,data,presetTheme,onDone,item}:any){
  const s=useSubmit(item?`/api/cases/${caseId}/events/${item.id}`:`/api/cases/${caseId}/events`,onDone,false,item?"PATCH":"POST");
  const selectedEvidence = item?.evidenceLinks?.map((link:any) => link.evidenceId) || [];
  return <form onSubmit={s.submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Date et heure du fait"><input className="field" name="occurredAt" type="datetime-local" required defaultValue={toDateTimeInput(item?.occurredAt)}/></Field><Field label="Thème"><input className="field" name="theme" required defaultValue={item?.theme||presetTheme} placeholder="Scolarité, santé, communication…"/></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Nature"><input className="field" name="type" required defaultValue={item?.type||""} placeholder="Rendez-vous, échange, paiement…"/></Field><Field label="Intitulé court"><input className="field" name="title" required defaultValue={item?.title||""} placeholder="Un titre descriptif"/></Field></div><Field label="Description factuelle"><textarea className="field min-h-28" name="description" required defaultValue={item?.description||""} placeholder="Décrivez ce qui s’est passé, sans qualification juridique ni supposition."/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Type de source"><select className="field" name="sourceType" defaultValue={item?.sourceType||"DIRECT"}><option value="DIRECT">Fait directement constaté</option><option value="REPORTED">Fait rapporté</option><option value="DOCUMENT">Issu d’un document</option><option value="INTERPRETATION">Déduction / interprétation</option><option value="UNVERIFIED">Non vérifié</option></select></Field><Field label="Précision sur la source"><input className="field" name="sourceDetails" defaultValue={item?.sourceDetails||""} placeholder="Auteur, document, contexte…"/></Field></div><Field label="Importance documentaire"><select className="field" name="importance" defaultValue={String(item?.importance||1)}><option value="1">Contexte</option><option value="2">Important</option><option value="3">Déterminant à examiner</option></select></Field>{data.evidence.length>0&&<Field label="Pièces déjà disponibles"><EvidencePicker evidence={data.evidence} selectedIds={selectedEvidence}/></Field>}<div className="grid gap-3 sm:grid-cols-2"><CheckField name="bool_needsVerification" label="Nécessite une vérification" defaultChecked={item?.needsVerification}/><CheckField name="bool_unfavorable" label="Élément potentiellement défavorable" defaultChecked={item?.unfavorable}/></div>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label={item?"Enregistrer les modifications":"Enregistrer"}/></form>
}
function EvidenceForm({caseId,onDone}:any){const s=useSubmit(`/api/cases/${caseId}/evidence`,onDone,true);return <form onSubmit={s.submit} className="space-y-4"><div className="rounded-2xl border-2 border-dashed border-stone-300 bg-white p-7 text-center"><Upload className="mx-auto text-forest"/><label className="mt-3 block text-sm font-semibold">Sélectionner le fichier original<input className="mt-3 block w-full text-sm" name="file" type="file" required accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg,.webp,.txt,.csv,.eml"/></label><p className="mt-2 text-xs text-stone-500">PDF, DOCX, XLSX, images, texte, CSV ou EML · 25 Mo maximum par défaut</p></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Source du document"><input className="field" name="source" required placeholder="Courriel reçu, banque, médecin…"/></Field><Field label="Catégorie"><select className="field" name="category"><option>Correspondance</option><option>Décision judiciaire</option><option>Santé</option><option>Scolarité</option><option>Finances</option><option>Photographie</option><option>Autre</option></select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Date du document"><input className="field" name="documentDate" type="date"/></Field><Field label="Confidentialité"><select className="field" name="confidentiality" defaultValue="SENSITIVE"><option value="STANDARD">Standard</option><option value="SENSITIVE">Sensible</option><option value="HIGHLY_SENSITIVE">Très sensible</option></select></Field></div><div className="rounded-xl bg-sage/70 p-4 text-xs leading-5 text-forest">L’original sera conservé sans modification. L’empreinte SHA‑256 contrôle son intégrité depuis l’import ; elle ne prouve pas son authenticité juridique.</div>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label="Importer la pièce"/></form>}
function EvidenceMetadataForm({caseId,item,onDone}:any){const s=useSubmit(`/api/cases/${caseId}/evidence/${item.id}`,onDone,false,"PATCH");return <form onSubmit={s.submit} className="space-y-4"><div className="rounded-xl border border-line bg-white p-4"><div className="text-xs font-semibold text-stone-400">ORIGINAL CONSERVÉ</div><div className="mt-1 font-semibold">{item.pieceReference} — {item.originalName}</div><div className="mt-1 text-xs text-stone-500">Importé le {formatDate(item.createdAt)} · empreinte SHA‑256 inchangée</div></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Source du document"><input className="field" name="source" required defaultValue={item.source}/></Field><Field label="Catégorie"><select className="field" name="category" defaultValue={item.category}><option>Correspondance</option><option>Décision judiciaire</option><option>Santé</option><option>Scolarité</option><option>Finances</option><option>Photographie</option><option>Autre</option></select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Date du document"><input className="field" name="documentDate" type="date" defaultValue={toDateInput(item.documentDate)}/></Field><Field label="Confidentialité"><select className="field" name="confidentiality" defaultValue={item.confidentiality}><option value="STANDARD">Standard</option><option value="SENSITIVE">Sensible</option><option value="HIGHLY_SENSITIVE">Très sensible</option></select></Field></div><Field label="Notes"><textarea className="field min-h-24" name="notes" defaultValue={item.notes||""}/></Field>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label="Enregistrer les modifications"/></form>}
function EvidencePicker({evidence,selectedIds=[]}:{evidence:any[];selectedIds?:string[]}){const[query,setQuery]=useState("");const[selected,setSelected]=useState(()=>new Set(selectedIds));const normalized=query.trim().toLocaleLowerCase("fr");const items=useMemo(()=>evidence.filter((item:any)=>!normalized||[item.pieceReference,item.originalName,item.category,item.source].some((value)=>value?.toLocaleLowerCase("fr").includes(normalized))),[evidence,normalized]);function toggle(id:string,checked:boolean){setSelected((current)=>{const next=new Set(current);if(checked)next.add(id);else next.delete(id);return next;});}return <div className="overflow-hidden rounded-xl border border-line bg-white">{Array.from(selected).map((id)=><input key={id} type="hidden" name="evidenceIds" value={id}/>)}<div className="relative border-b border-line p-2"><Search className="absolute left-5 top-5 text-stone-400" size={15}/><input className="field !py-2 pl-9 text-sm" value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Rechercher une pièce…" aria-label="Rechercher dans les pièces disponibles"/></div><div className="grid max-h-44 gap-1 overflow-auto p-3">{items.map((item:any)=><label className="flex items-start gap-2 rounded-lg p-2 text-sm hover:bg-stone-50" key={item.id}><input className="mt-0.5" type="checkbox" checked={selected.has(item.id)} onChange={(event)=>toggle(item.id,event.target.checked)}/><span><span className="font-medium">{item.pieceReference} — {item.originalName}</span><span className="mt-0.5 block text-xs text-stone-500">Document : {formatDate(item.documentDate)} · {item.category}</span></span></label>)}{!items.length&&<span className="p-3 text-center text-xs text-stone-500">Aucune pièce ne correspond à cette recherche.</span>}</div></div>}
function RequestForm({caseId,data,onDone,item}:any){const s=useSubmit(item?`/api/cases/${caseId}/requests/${item.id}`:`/api/cases/${caseId}/requests`,onDone,false,item?"PATCH":"POST");const selectedEvents=item?.eventLinks?.map((link:any)=>link.eventId)||[];const selectedEvidence=item?.evidenceLinks?.map((link:any)=>link.evidenceId)||[];return <form onSubmit={s.submit} className="space-y-4"><Field label="Demande ou point à discuter"><input className="field" name="title" required defaultValue={item?.title||""} placeholder="Résidence, vacances, contribution…"/></Field><Field label="Objectif du parent"><textarea className="field min-h-24" name="objective" required defaultValue={item?.objective||""}/></Field><Field label="Situation actuelle"><textarea className="field min-h-20" name="currentSituation" defaultValue={item?.currentSituation||""}/></Field><Field label="Changement envisagé"><textarea className="field min-h-20" name="requestedChange" defaultValue={item?.requestedChange||""}/></Field><Field label="Conséquences pratiques pour l’enfant"><textarea className="field min-h-20" name="childImpact" defaultValue={item?.childImpact||""}/></Field><Field label="Points à arbitrer par l’avocat"><textarea className="field min-h-20" name="lawyerArbitration" defaultValue={item?.lawyerArbitration||""}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Faits associés"><div className="grid max-h-40 gap-2 overflow-auto rounded-xl border border-line bg-white p-3">{data.events.map((event:any)=><label className="flex items-start gap-2 text-xs" key={event.id}><input className="mt-0.5" type="checkbox" name="eventIds" value={event.id} defaultChecked={selectedEvents.includes(event.id)}/><span>{event.title}</span></label>)}{!data.events.length&&<span className="text-xs text-stone-500">Aucun fait disponible</span>}</div></Field><Field label="Preuves associées"><EvidencePicker evidence={data.evidence} selectedIds={selectedEvidence}/></Field></div>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label={item?"Enregistrer les modifications":"Enregistrer"}/></form>}
function ClaimForm({caseId,onDone,item}:any){const s=useSubmit(item?`/api/cases/${caseId}/allegations/${item.id}`:`/api/cases/${caseId}/allegations`,onDone,false,item?"PATCH":"POST");return <form onSubmit={s.submit} className="space-y-4"><Field label="Thème"><input className="field" name="theme" required defaultValue={item?.theme||""} placeholder="Organisation, santé, finances…"/></Field><Field label="Allégation"><textarea className="field min-h-24" name="allegation" required defaultValue={item?.allegation||""}/></Field><Field label="Source"><input className="field" name="source" required defaultValue={item?.source||""} placeholder="Courrier, propos rapporté, conclusions…"/></Field><Field label="Réponse factuelle"><textarea className="field min-h-24" name="response" defaultValue={item?.response||""}/></Field><Field label="Point restant à vérifier"><textarea className="field min-h-20" name="verificationPoint" defaultValue={item?.verificationPoint||""}/></Field><div className="grid gap-3 sm:grid-cols-2"><CheckField name="bool_contested" label="Allégation contestée" defaultChecked={item?.contested}/><CheckField name="bool_unfavorableToUser" label="Élément défavorable à l’utilisateur" defaultChecked={item?.unfavorableToUser}/></div>{s.error&&<FormError text={s.error}/>}<Submit busy={s.busy} label={item?"Enregistrer les modifications":"Enregistrer"}/></form>}
function Field({label,children}:{label:string;children:ReactNode}){return <label><span className="label">{label}</span>{children}</label>}
function CheckField({name,label,defaultChecked=false}:{name:string;label:string;defaultChecked?:boolean}){return <label className="flex min-h-12 items-center gap-3 rounded-xl border border-line bg-white px-4 py-3 text-sm"><input name={name} type="checkbox" defaultChecked={defaultChecked}/><span>{label}</span></label>}
function FormError({text}:{text:string}){return <p role="alert" className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800">{text}</p>}
